// F32x2 holds 2 f32 lanes (64 bits).
pub struct F32x2 {
mut:
	values [2]f32
}

// f32x2 creates a F32x2 from its lanes in lane order.
pub fn f32x2(a f32, b f32) F32x2 {
	return F32x2{
		values: [a, b]!
	}
}

// splat_f32x2 returns a F32x2 with every lane set to value.
pub fn splat_f32x2(value f32) F32x2 {
	return F32x2{
		values: [2]f32{init: value}
	}
}

// from_array_f32x2 returns a F32x2 holding values in lane order.
pub fn from_array_f32x2(values [2]f32) F32x2 {
	return F32x2{
		values: values
	}
}

// load_f32x2 loads 2 values from the start of src.
// It returns an error if src has fewer than 2 values.
pub fn load_f32x2(src []f32) !F32x2 {
	if src.len < 2 {
		return error('simd.load_f32x2 needs at least 2 values')
	}
	return load_f32x2_at(src, 0)
}

// load_f32x2_part loads up to 2 values from src and zero-fills the remaining lanes.
// It returns an error if src has more than 2 values.
@[direct_array_access]
pub fn load_f32x2_part(src []f32) !F32x2 {
	if src.len > 2 {
		return error('simd.load_f32x2_part accepts at most 2 values')
	}
	mut r := F32x2{}
	for i in 0 .. src.len {
		r.values[i] = src[i]
	}
	return r
}

// load_f32x2_at loads 2 values starting at src[offset].
// It panics if offset is negative or fewer than 2 values follow it.
@[direct_array_access]
pub fn load_f32x2_at(src []f32, offset int) F32x2 {
	if offset < 0 || offset > src.len - 2 {
		range_panic('simd.load_f32x2_at', offset, src.len)
	}
	mut r := F32x2{}
	for i in 0 .. 2 {
		r.values[i] = src[offset + i]
	}
	return r
}

// select_f32x2 returns the lanes of a where mask is set and the lanes of b
// where it is clear.
@[direct_array_access]
pub fn select_f32x2(mask Mask32x2, a F32x2, b F32x2) F32x2 {
	mut r := F32x2{}
	$if @BACKEND == 'c' {
		native_select_f32(&mask.values[0], &a.values[0], &b.values[0], &r.values[0], 2)
	} $else {
		for i in 0 .. 2 {
			r.values[i] = if mask.values[i] != 0 { a.values[i] } else { b.values[i] }
		}
	}
	return r
}

// to_array returns the lanes in order.
pub fn (v F32x2) to_array() [2]f32 {
	return v.values
}

// [] returns lane i. It panics if i is out of range.
@[direct_array_access]
pub fn (v F32x2) [] (i int) f32 {
	if i < 0 || i >= 2 {
		lane_panic(i, 2)
	}
	return v.values[i]
}

// []= sets lane i to value. It panics if i is out of range.
@[direct_array_access]
pub fn (mut v F32x2) []= (i int, value f32) {
	if i < 0 || i >= 2 {
		lane_panic(i, 2)
	}
	v.values[i] = value
}

// store writes all 2 lanes to the start of dst.
// It returns an error if dst has fewer than 2 elements.
pub fn (v F32x2) store(mut dst []f32) ! {
	if dst.len < 2 {
		return error('simd.F32x2.store needs at least 2 values')
	}
	v.store_at(mut dst, 0)
}

// store_part writes one lane for each element of dst, up to 2 elements.
// It returns an error if dst has more than 2 elements.
@[direct_array_access]
pub fn (v F32x2) store_part(mut dst []f32) ! {
	if dst.len > 2 {
		return error('simd.F32x2.store_part accepts at most 2 values')
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&f32(dst.data) + 0, &v.values[0], dst.len * int(sizeof(f32))) }
	} $else {
		for i in 0 .. dst.len {
			dst[0 + i] = v.values[i]
		}
	}
}

// store_at writes all 2 lanes to dst, starting at dst[offset].
// It panics if offset is negative or fewer than 2 elements follow it.
@[direct_array_access]
pub fn (v F32x2) store_at(mut dst []f32, offset int) {
	if offset < 0 || offset > dst.len - 2 {
		range_panic('simd.F32x2.store_at', offset, dst.len)
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&f32(dst.data) + offset, &v.values[0], 2 * int(sizeof(f32))) }
	} $else {
		for i in 0 .. 2 {
			dst[offset + i] = v.values[i]
		}
	}
}

// + adds corresponding lanes.
@[direct_array_access]
pub fn (a F32x2) + (b F32x2) F32x2 {
	mut r := F32x2{}
	$if @BACKEND == 'c' {
		native_add_f32(&a.values[0], &b.values[0], &r.values[0], 2)
	} $else {
		for i in 0 .. 2 {
			r.values[i] = a.values[i] + b.values[i]
		}
	}
	return r
}

