// minimum returns the smaller of each pair of lanes.
// When one lane is NaN, the other lane is returned. Equal lanes, such as
// -0.0 and 0.0, return the lane of a.
@[direct_array_access]
pub fn (a F32x2) minimum(b F32x2) F32x2 {
	mut r := F32x2{}
	$if @BACKEND == 'c' {
		native_min_f32(&a.values[0], &b.values[0], &r.values[0], 2)
	} $else {
		for i in 0 .. 2 {
			x := a.values[i]
			y := b.values[i]
			r.values[i] = if y < x || x != x { y } else { x }
		}
	}
	return r
}

