// sum adds the lanes in lane order.
@[direct_array_access]
pub fn (v F32x2) sum() f32 {
	mut acc := v.values[0]
	for i in 1 .. 2 {
		acc += v.values[i]
	}
	return acc
}

// min_element returns the index of the first lane holding the smallest value.
// NaN lanes are ignored. If every lane is NaN, it returns 0.
@[direct_array_access]
pub fn (v F32x2) min_element() int {
	mut best := 0
	for i in 1 .. 2 {
		x := v.values[i]
		y := v.values[best]
		if x < y || (y != y && x == x) {
			best = i
		}
	}
	return best
}

// min returns the smallest lane value, the lane at index min_element().
// NaN lanes are ignored unless every lane is NaN.
@[direct_array_access]
pub fn (v F32x2) min() f32 {
	return v.values[v.min_element()]
}

