// dot multiplies corresponding lanes and adds the products in lane order.
pub fn (a F32x2) dot(b F32x2) f32 {
	return (a * b).sum()
}

// to_i32x2 converts each lane to i32.
// It truncates toward zero, maps NaN to 0 and saturates values outside the
// range of i32.
@[direct_array_access]
pub fn (v F32x2) to_i32x2() I32x2 {
	mut r := I32x2{}
	for i in 0 .. 2 {
		r.values[i] = f32_to_i32(v.values[i])
	}
