	return F64x2{
		values: values
	}
}

// load_f64x2 loads 2 values from the start of src.
// It returns an error if src has fewer than 2 values.
pub fn load_f64x2(src []f64) !F64x2 {
	if src.len < 2 {
		return error('simd.load_f64x2 needs at least 2 values')
	}
	return load_f64x2_at(src, 0)
}

// load_f64x2_part loads up to 2 values from src and zero-fills the remaining lanes.
// It returns an error if src has more than 2 values.
@[direct_array_access]
pub fn load_f64x2_part(src []f64) !F64x2 {
	if src.len > 2 {
		return error('simd.load_f64x2_part accepts at most 2 values')
	}
	mut r := F64x2{}
	for i in 0 .. src.len {
		r.values[i] = src[i]
	}
	return r
}

// load_f64x2_at loads 2 values starting at src[offset].
// It panics if offset is negative or fewer than 2 values follow it.
@[direct_array_access]
pub fn load_f64x2_at(src []f64, offset int) F64x2 {
	if offset < 0 || offset > src.len - 2 {
		range_panic('simd.load_f64x2_at', offset, src.len)
	}
	mut r := F64x2{}
	for i in 0 .. 2 {
		r.values[i] = src[offset + i]
	}
	return r
}

// select_f64x2 returns the lanes of a where mask is set and the lanes of b
// where it is clear.
@[direct_array_access]
pub fn select_f64x2(mask Mask64x2, a F64x2, b F64x2) F64x2 {
	mut r := F64x2{}
	$if @BACKEND == 'c' {
		native_select_f64(&mask.values[0], &a.values[0], &b.values[0], &r.values[0], 2)
	} $else {
		for i in 0 .. 2 {
			r.values[i] = if mask.values[i] != 0 { a.values[i] } else { b.values[i] }
		}
	}
	return r
}

