	return v.values
}

// [] returns lane i. It panics if i is out of range.
@[direct_array_access]
pub fn (v F64x2) [] (i int) f64 {
	if i < 0 || i >= 2 {
		lane_panic(i, 2)
	}
	return v.values[i]
}

// []= sets lane i to value. It panics if i is out of range.
@[direct_array_access]
pub fn (mut v F64x2) []= (i int, value f64) {
	if i < 0 || i >= 2 {
		lane_panic(i, 2)
	}
	v.values[i] = value
}

// store writes all 2 lanes to the start of dst.
// It returns an error if dst has fewer than 2 elements.
pub fn (v F64x2) store(mut dst []f64) ! {
	if dst.len < 2 {
		return error('simd.F64x2.store needs at least 2 values')
	}
	v.store_at(mut dst, 0)
}

// store_part writes one lane for each element of dst, up to 2 elements.
// It returns an error if dst has more than 2 elements.
@[direct_array_access]
pub fn (v F64x2) store_part(mut dst []f64) ! {
	if dst.len > 2 {
		return error('simd.F64x2.store_part accepts at most 2 values')
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&f64(dst.data) + 0, &v.values[0], dst.len * int(sizeof(f64))) }
	} $else {
		for i in 0 .. dst.len {
			dst[0 + i] = v.values[i]
		}
	}
}

// store_at writes all 2 lanes to dst, starting at dst[offset].
// It panics if offset is negative or fewer than 2 elements follow it.
@[direct_array_access]
pub fn (v F64x2) store_at(mut dst []f64, offset int) {
	if offset < 0 || offset > dst.len - 2 {
		range_panic('simd.F64x2.store_at', offset, dst.len)
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&f64(dst.data) + offset, &v.values[0], 2 * int(sizeof(f64))) }
	} $else {
		for i in 0 .. 2 {
			dst[offset + i] = v.values[i]
		}
	}
}

