// min_element returns the index of the first lane holding the smallest value.
// NaN lanes are ignored. If every lane is NaN, it returns 0.
@[direct_array_access]
pub fn (v F64x8) min_element() int {
	mut best := 0
	for i in 1 .. 8 {
		x := v.values[i]
		y := v.values[best]
		if x < y || (y != y && x == x) {
			best = i
		}
	}
	return best
}

// min returns the smallest lane value, the lane at index min_element().
