// I8x8 holds 8 i8 lanes (64 bits).
pub struct I8x8 {
mut:
	values [8]i8
}

// i8x8 creates a I8x8 from its lanes in lane order.
pub fn i8x8(a i8, b i8, c i8, d i8, e i8, f i8, g i8, h i8) I8x8 {
	return I8x8{
		values: [a, b, c, d, e, f, g, h]!
	}
}

// splat_i8x8 returns a I8x8 with every lane set to value.
pub fn splat_i8x8(value i8) I8x8 {
	return I8x8{
		values: [8]i8{init: value}
	}
}

// from_array_i8x8 returns a I8x8 holding values in lane order.
pub fn from_array_i8x8(values [8]i8) I8x8 {
	return I8x8{
		values: values
	}
}

// load_i8x8 loads 8 values from the start of src.
// It returns an error if src has fewer than 8 values.
pub fn load_i8x8(src []i8) !I8x8 {
	if src.len < 8 {
		return error('simd.load_i8x8 needs at least 8 values')
	}
	return load_i8x8_at(src, 0)
}

// load_i8x8_part loads up to 8 values from src and zero-fills the remaining lanes.
// It returns an error if src has more than 8 values.
@[direct_array_access]
pub fn load_i8x8_part(src []i8) !I8x8 {
	if src.len > 8 {
		return error('simd.load_i8x8_part accepts at most 8 values')
	}
	mut r := I8x8{}
	for i in 0 .. src.len {
		r.values[i] = src[i]
	}
	return r
}

// load_i8x8_at loads 8 values starting at src[offset].
// It panics if offset is negative or fewer than 8 values follow it.
@[direct_array_access]
pub fn load_i8x8_at(src []i8, offset int) I8x8 {
	if offset < 0 || offset > src.len - 8 {
		range_panic('simd.load_i8x8_at', offset, src.len)
	}
	mut r := I8x8{}
	for i in 0 .. 8 {
		r.values[i] = src[offset + i]
	}
	return r
}

// select_i8x8 returns the lanes of a where mask is set and the lanes of b
// where it is clear.
@[direct_array_access]
pub fn select_i8x8(mask Mask8x8, a I8x8, b I8x8) I8x8 {
	mut r := I8x8{}
	$if @BACKEND == 'c' {
		native_select_i8(&mask.values[0], &a.values[0], &b.values[0], &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			r.values[i] = if mask.values[i] != 0 { a.values[i] } else { b.values[i] }
		}
	}
	return r
}

// to_array returns the lanes in order.
pub fn (v I8x8) to_array() [8]i8 {
	return v.values
}

// [] returns lane i. It panics if i is out of range.
@[direct_array_access]
pub fn (v I8x8) [] (i int) i8 {
	if i < 0 || i >= 8 {
		lane_panic(i, 8)
	}
	return v.values[i]
}

// []= sets lane i to value. It panics if i is out of range.
@[direct_array_access]
pub fn (mut v I8x8) []= (i int, value i8) {
	if i < 0 || i >= 8 {
		lane_panic(i, 8)
	}
	v.values[i] = value
}

// store writes all 8 lanes to the start of dst.
// It returns an error if dst has fewer than 8 elements.
pub fn (v I8x8) store(mut dst []i8) ! {
	if dst.len < 8 {
		return error('simd.I8x8.store needs at least 8 values')
	}
	v.store_at(mut dst, 0)
}

// store_part writes one lane for each element of dst, up to 8 elements.
// It returns an error if dst has more than 8 elements.
@[direct_array_access]
pub fn (v I8x8) store_part(mut dst []i8) ! {
	if dst.len > 8 {
		return error('simd.I8x8.store_part accepts at most 8 values')
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&i8(dst.data) + 0, &v.values[0], dst.len * int(sizeof(i8))) }
	} $else {
		for i in 0 .. dst.len {
			dst[0 + i] = v.values[i]
		}
	}
}

// store_at writes all 8 lanes to dst, starting at dst[offset].
// It panics if offset is negative or fewer than 8 elements follow it.
@[direct_array_access]
pub fn (v I8x8) store_at(mut dst []i8, offset int) {
	if offset < 0 || offset > dst.len - 8 {
		range_panic('simd.I8x8.store_at', offset, dst.len)
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&i8(dst.data) + offset, &v.values[0], 8 * int(sizeof(i8))) }
	} $else {
		for i in 0 .. 8 {
			dst[offset + i] = v.values[i]
		}
	}
}

