// shl shifts each lane left by count bits.
// A count of 8 or more shifts every bit out and returns zero lanes.
@[direct_array_access]
pub fn (a I8x8) shl(count u32) I8x8 {
	if count >= 8 {
		return I8x8{}
	}
	mut r := I8x8{}
	$if @BACKEND == 'c' {
		native_shl_i8(&a.values[0], count, &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			r.values[i] = i8(u32(a.values[i]) << count)
		}
	}
	return r
}

// shr shifts each lane right by count bits.
// The shift is arithmetic: it copies the sign bit, and a count of 8 or
// more fills each lane with its sign bit.
@[direct_array_access]
pub fn (a I8x8) shr(count u32) I8x8 {
	c := if count >= 8 { u32(7) } else { count }
	mut r := I8x8{}
	$if @BACKEND == 'c' {
		native_shr_i8(&a.values[0], c, &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			r.values[i] = a.values[i] >> c
		}
	}
	return r
}

