// neg negates each lane, wrapping min_i8 to itself.
@[direct_array_access]
pub fn (a I8x16) neg() I8x16 {
	mut r := I8x16{}
	$if @BACKEND == 'c' {
		native_neg_i8(&a.values[0], &r.values[0], 16)
	} $else {
		for i in 0 .. 16 {
			r.values[i] = i8(u32(0) - u32(a.values[i]))
		}
	}
	return r
}

// abs returns the absolute value of each lane. min_i8 wraps to itself.
@[direct_array_access]
pub fn (a I8x16) abs() I8x16 {
	mut r := I8x16{}
	$if @BACKEND == 'c' {
		native_abs_i8(&a.values[0], &r.values[0], 16)
	} $else {
		for i in 0 .. 16 {
			x := a.values[i]
			r.values[i] = if x < 0 { i8(u32(0) - u32(x)) } else { x }
		}
	}
	return r
}

