// not returns the bitwise complement of each lane.
@[direct_array_access]
pub fn (a I8x16) not() I8x16 {
	mut r := I8x16{}
	$if @BACKEND == 'c' {
		native_not_i8(&a.values[0], &r.values[0], 16)
	} $else {
