// shl shifts each lane left by count bits.
// A count of 8 or more shifts every bit out and returns zero lanes.
@[direct_array_access]
pub fn (a I8x16) shl(count u32) I8x16 {
	if count >= 8 {
		return I8x16{}
	}
	mut r := I8x16{}
	$if @BACKEND == 'c' {
		native_shl_i8(&a.values[0], count, &r.values[0], 16)
	} $else {
		for i in 0 .. 16 {
			r.values[i] = i8(u32(a.values[i]) << count)
		}
	}
	return r
}

// shr shifts each lane right by count bits.
// The shift is arithmetic: it copies the sign bit, and a count of 8 or
// more fills each lane with its sign bit.
@[direct_array_access]
pub fn (a I8x16) shr(count u32) I8x16 {
	c := if count >= 8 { u32(7) } else { count }
	mut r := I8x16{}
	$if @BACKEND == 'c' {
		native_shr_i8(&a.values[0], c, &r.values[0], 16)
	} $else {
		for i in 0 .. 16 {
			r.values[i] = a.values[i] >> c
		}
	}
	return r
}

// sum adds the lanes, wrapping on overflow.
@[direct_array_access]
pub fn (v I8x16) sum() i8 {
	mut acc := u32(0)
	for i in 0 .. 16 {
		acc += u32(v.values[i])
	}
	return i8(acc)
}

// min_element returns the index of the first lane holding the smallest value.
@[direct_array_access]
pub fn (v I8x16) min_element() int {
	mut best := 0
	for i in 1 .. 16 {
		if v.values[i] < v.values[best] {
			best = i
		}
	}
	return best
}

// min returns the smallest lane value, the lane at index min_element().
@[direct_array_access]
pub fn (v I8x16) min() i8 {
	return v.values[v.min_element()]
}

// max_element returns the index of the first lane holding the largest value.
@[direct_array_access]
pub fn (v I8x16) max_element() int {
	mut best := 0
	for i in 1 .. 16 {
		if v.values[i] > v.values[best] {
			best = i
		}
	}
	return best
}

// max returns the largest lane value, the lane at index max_element().
@[direct_array_access]
pub fn (v I8x16) max() i8 {
	return v.values[v.max_element()]
}

// dot multiplies corresponding lanes and adds the products, wrapping on overflow.
pub fn (a I8x16) dot(b I8x16) i8 {
	return (a * b).sum()
}

// to_u8x16 converts each lane to u8.
// It keeps the bits of each lane, so values wrap modulo 2^8.
@[direct_array_access]
pub fn (v I8x16) to_u8x16() U8x16 {
	mut r := U8x16{}
	for i in 0 .. 16 {
		r.values[i] = u8(v.values[i])
	}
	return r
}

// I8x32 holds 32 i8 lanes (256 bits).
pub struct I8x32 {
mut:
	values [32]i8
}

// splat_i8x32 returns a I8x32 with every lane set to value.
pub fn splat_i8x32(value i8) I8x32 {
	return I8x32{
		values: [32]i8{init: value}
	}
}

// from_array_i8x32 returns a I8x32 holding values in lane order.
pub fn from_array_i8x32(values [32]i8) I8x32 {
	return I8x32{
		values: values
	}
}

// load_i8x32 loads 32 values from the start of src.
// It returns an error if src has fewer than 32 values.
pub fn load_i8x32(src []i8) !I8x32 {
	if src.len < 32 {
		return error('simd.load_i8x32 needs at least 32 values')
	}
	return load_i8x32_at(src, 0)
}

// load_i8x32_part loads up to 32 values from src and zero-fills the remaining lanes.
// It returns an error if src has more than 32 values.
@[direct_array_access]
pub fn load_i8x32_part(src []i8) !I8x32 {
	if src.len > 32 {
		return error('simd.load_i8x32_part accepts at most 32 values')
	}
	mut r := I8x32{}
	for i in 0 .. src.len {
		r.values[i] = src[i]
	}
	return r
}

// load_i8x32_at loads 32 values starting at src[offset].
// It panics if offset is negative or fewer than 32 values follow it.
@[direct_array_access]
pub fn load_i8x32_at(src []i8, offset int) I8x32 {
	if offset < 0 || offset > src.len - 32 {
		range_panic('simd.load_i8x32_at', offset, src.len)
	}
	mut r := I8x32{}
	for i in 0 .. 32 {
		r.values[i] = src[offset + i]
	}
	return r
}

// select_i8x32 returns the lanes of a where mask is set and the lanes of b
// where it is clear.
@[direct_array_access]
pub fn select_i8x32(mask Mask8x32, a I8x32, b I8x32) I8x32 {
	mut r := I8x32{}
	$if @BACKEND == 'c' {
		native_select_i8(&mask.values[0], &a.values[0], &b.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			r.values[i] = if mask.values[i] != 0 { a.values[i] } else { b.values[i] }
		}
	}
	return r
}

// to_array returns the lanes in order.
