// from_array_i8x64 returns a I8x64 holding values in lane order.
pub fn from_array_i8x64(values [64]i8) I8x64 {
	return I8x64{
		values: values
	}
}

// load_i8x64 loads 64 values from the start of src.
// It returns an error if src has fewer than 64 values.
pub fn load_i8x64(src []i8) !I8x64 {
	if src.len < 64 {
		return error('simd.load_i8x64 needs at least 64 values')
	}
	return load_i8x64_at(src, 0)
}

// load_i8x64_part loads up to 64 values from src and zero-fills the remaining lanes.
// It returns an error if src has more than 64 values.
@[direct_array_access]
pub fn load_i8x64_part(src []i8) !I8x64 {
	if src.len > 64 {
		return error('simd.load_i8x64_part accepts at most 64 values')
	}
	mut r := I8x64{}
	for i in 0 .. src.len {
		r.values[i] = src[i]
	}
	return r
}

// load_i8x64_at loads 64 values starting at src[offset].
// It panics if offset is negative or fewer than 64 values follow it.
@[direct_array_access]
pub fn load_i8x64_at(src []i8, offset int) I8x64 {
	if offset < 0 || offset > src.len - 64 {
		range_panic('simd.load_i8x64_at', offset, src.len)
	}
	mut r := I8x64{}
	for i in 0 .. 64 {
		r.values[i] = src[offset + i]
	}
	return r
}

// select_i8x64 returns the lanes of a where mask is set and the lanes of b
// where it is clear.
@[direct_array_access]
pub fn select_i8x64(mask Mask8x64, a I8x64, b I8x64) I8x64 {
	mut r := I8x64{}
	$if @BACKEND == 'c' {
		native_select_i8(&mask.values[0], &a.values[0], &b.values[0], &r.values[0], 64)
	} $else {
		for i in 0 .. 64 {
			r.values[i] = if mask.values[i] != 0 { a.values[i] } else { b.values[i] }
		}
	}
	return r
}

// to_array returns the lanes in order.
pub fn (v I8x64) to_array() [64]i8 {
	return v.values
}

// [] returns lane i. It panics if i is out of range.
@[direct_array_access]
pub fn (v I8x64) [] (i int) i8 {
	if i < 0 || i >= 64 {
		lane_panic(i, 64)
	}
	return v.values[i]
}

// []= sets lane i to value. It panics if i is out of range.
@[direct_array_access]
pub fn (mut v I8x64) []= (i int, value i8) {
	if i < 0 || i >= 64 {
		lane_panic(i, 64)
	}
	v.values[i] = value
}

// store writes all 64 lanes to the start of dst.
// It returns an error if dst has fewer than 64 elements.
pub fn (v I8x64) store(mut dst []i8) ! {
	if dst.len < 64 {
		return error('simd.I8x64.store needs at least 64 values')
	}
	v.store_at(mut dst, 0)
}

// store_part writes one lane for each element of dst, up to 64 elements.
// It returns an error if dst has more than 64 elements.
@[direct_array_access]
pub fn (v I8x64) store_part(mut dst []i8) ! {
	if dst.len > 64 {
		return error('simd.I8x64.store_part accepts at most 64 values')
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&i8(dst.data) + 0, &v.values[0], dst.len * int(sizeof(i8))) }
	} $else {
		for i in 0 .. dst.len {
			dst[0 + i] = v.values[i]
		}
	}
}

// store_at writes all 64 lanes to dst, starting at dst[offset].
// It panics if offset is negative or fewer than 64 elements follow it.
@[direct_array_access]
pub fn (v I8x64) store_at(mut dst []i8, offset int) {
	if offset < 0 || offset > dst.len - 64 {
		range_panic('simd.I8x64.store_at', offset, dst.len)
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&i8(dst.data) + offset, &v.values[0], 64 * int(sizeof(i8))) }
	} $else {
		for i in 0 .. 64 {
			dst[offset + i] = v.values[i]
		}
	}
}

