	if src.len > 4 {
		return error('simd.load_i16x4_part accepts at most 4 values')
	}
	mut r := I16x4{}
	for i in 0 .. src.len {
		r.values[i] = src[i]
	}
	return r
}

// load_i16x4_at loads 4 values starting at src[offset].
// It panics if offset is negative or fewer than 4 values follow it.
@[direct_array_access]
pub fn load_i16x4_at(src []i16, offset int) I16x4 {
	if offset < 0 || offset > src.len - 4 {
		range_panic('simd.load_i16x4_at', offset, src.len)
	}
	mut r := I16x4{}
	for i in 0 .. 4 {
		r.values[i] = src[offset + i]
	}
	return r
}

// select_i16x4 returns the lanes of a where mask is set and the lanes of b
// where it is clear.
@[direct_array_access]
pub fn select_i16x4(mask Mask16x4, a I16x4, b I16x4) I16x4 {
	mut r := I16x4{}
	$if @BACKEND == 'c' {
		native_select_i16(&mask.values[0], &a.values[0], &b.values[0], &r.values[0], 4)
	} $else {
		for i in 0 .. 4 {
			r.values[i] = if mask.values[i] != 0 { a.values[i] } else { b.values[i] }
		}
	}
	return r
}

// to_array returns the lanes in order.
pub fn (v I16x4) to_array() [4]i16 {
	return v.values
}

// [] returns lane i. It panics if i is out of range.
@[direct_array_access]
pub fn (v I16x4) [] (i int) i16 {
	if i < 0 || i >= 4 {
		lane_panic(i, 4)
	}
	return v.values[i]
}

// []= sets lane i to value. It panics if i is out of range.
@[direct_array_access]
pub fn (mut v I16x4) []= (i int, value i16) {
	if i < 0 || i >= 4 {
		lane_panic(i, 4)
	}
	v.values[i] = value
}

// store writes all 4 lanes to the start of dst.
// It returns an error if dst has fewer than 4 elements.
pub fn (v I16x4) store(mut dst []i16) ! {
	if dst.len < 4 {
		return error('simd.I16x4.store needs at least 4 values')
	}
	v.store_at(mut dst, 0)
}

// store_part writes one lane for each element of dst, up to 4 elements.
// It returns an error if dst has more than 4 elements.
@[direct_array_access]
pub fn (v I16x4) store_part(mut dst []i16) ! {
	if dst.len > 4 {
		return error('simd.I16x4.store_part accepts at most 4 values')
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&i16(dst.data) + 0, &v.values[0], dst.len * int(sizeof(i16))) }
	} $else {
		for i in 0 .. dst.len {
			dst[0 + i] = v.values[i]
		}
	}
}

// store_at writes all 4 lanes to dst, starting at dst[offset].
// It panics if offset is negative or fewer than 4 elements follow it.
@[direct_array_access]
pub fn (v I16x4) store_at(mut dst []i16, offset int) {
	if offset < 0 || offset > dst.len - 4 {
		range_panic('simd.I16x4.store_at', offset, dst.len)
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&i16(dst.data) + offset, &v.values[0], 4 * int(sizeof(i16))) }
	} $else {
		for i in 0 .. 4 {
			dst[offset + i] = v.values[i]
		}
	}
}

