// not returns the bitwise complement of each lane.
@[direct_array_access]
pub fn (a I16x4) not() I16x4 {
	mut r := I16x4{}
	$if @BACKEND == 'c' {
		native_not_i16(&a.values[0], &r.values[0], 4)
	} $else {
