// shl shifts each lane left by count bits.
// A count of 16 or more shifts every bit out and returns zero lanes.
@[direct_array_access]
pub fn (a I16x4) shl(count u32) I16x4 {
	if count >= 16 {
		return I16x4{}
	}
	mut r := I16x4{}
	$if @BACKEND == 'c' {
		native_shl_i16(&a.values[0], count, &r.values[0], 4)
	} $else {
		for i in 0 .. 4 {
			r.values[i] = i16(u32(a.values[i]) << count)
		}
	}
	return r
}

// shr shifts each lane right by count bits.
// The shift is arithmetic: it copies the sign bit, and a count of 16 or
// more fills each lane with its sign bit.
@[direct_array_access]
pub fn (a I16x4) shr(count u32) I16x4 {
	c := if count >= 16 { u32(15) } else { count }
	mut r := I16x4{}
	$if @BACKEND == 'c' {
		native_shr_i16(&a.values[0], c, &r.values[0], 4)
	} $else {
		for i in 0 .. 4 {
			r.values[i] = a.values[i] >> c
		}
	}
	return r
}

// sum adds the lanes, wrapping on overflow.
@[direct_array_access]
pub fn (v I16x4) sum() i16 {
	mut acc := u32(0)
	for i in 0 .. 4 {
		acc += u32(v.values[i])
	}
	return i16(acc)
}

// min_element returns the index of the first lane holding the smallest value.
@[direct_array_access]
pub fn (v I16x4) min_element() int {
	mut best := 0
	for i in 1 .. 4 {
		if v.values[i] < v.values[best] {
			best = i
		}
	}
	return best
}

// min returns the smallest lane value, the lane at index min_element().
@[direct_array_access]
pub fn (v I16x4) min() i16 {
	return v.values[v.min_element()]
}

// max_element returns the index of the first lane holding the largest value.
@[direct_array_access]
pub fn (v I16x4) max_element() int {
	mut best := 0
	for i in 1 .. 4 {
		if v.values[i] > v.values[best] {
			best = i
		}
	}
	return best
}

// max returns the largest lane value, the lane at index max_element().
@[direct_array_access]
pub fn (v I16x4) max() i16 {
	return v.values[v.max_element()]
