// to_u16x4 converts each lane to u16.
// It keeps the bits of each lane, so values wrap modulo 2^16.
@[direct_array_access]
pub fn (v I16x4) to_u16x4() U16x4 {
	mut r := U16x4{}
	for i in 0 .. 4 {
