// load_i16x16 loads 16 values from the start of src.
// It returns an error if src has fewer than 16 values.
pub fn load_i16x16(src []i16) !I16x16 {
	if src.len < 16 {
		return error('simd.load_i16x16 needs at least 16 values')
	}
	return load_i16x16_at(src, 0)
}

// load_i16x16_part loads up to 16 values from src and zero-fills the remaining lanes.
// It returns an error if src has more than 16 values.
@[direct_array_access]
pub fn load_i16x16_part(src []i16) !I16x16 {
	if src.len > 16 {
		return error('simd.load_i16x16_part accepts at most 16 values')
	}
	mut r := I16x16{}
	for i in 0 .. src.len {
		r.values[i] = src[i]
	}
	return r
}

// load_i16x16_at loads 16 values starting at src[offset].
// It panics if offset is negative or fewer than 16 values follow it.
@[direct_array_access]
pub fn load_i16x16_at(src []i16, offset int) I16x16 {
	if offset < 0 || offset > src.len - 16 {
		range_panic('simd.load_i16x16_at', offset, src.len)
	}
	mut r := I16x16{}
	for i in 0 .. 16 {
		r.values[i] = src[offset + i]
	}
	return r
}

// select_i16x16 returns the lanes of a where mask is set and the lanes of b
// where it is clear.
@[direct_array_access]
pub fn select_i16x16(mask Mask16x16, a I16x16, b I16x16) I16x16 {
	mut r := I16x16{}
	$if @BACKEND == 'c' {
		native_select_i16(&mask.values[0], &a.values[0], &b.values[0], &r.values[0], 16)
	} $else {
		for i in 0 .. 16 {
			r.values[i] = if mask.values[i] != 0 { a.values[i] } else { b.values[i] }
		}
	}
	return r
}

