// [] returns lane i. It panics if i is out of range.
@[direct_array_access]
pub fn (v I16x16) [] (i int) i16 {
	if i < 0 || i >= 16 {
		lane_panic(i, 16)
	}
	return v.values[i]
}

// []= sets lane i to value. It panics if i is out of range.
@[direct_array_access]
pub fn (mut v I16x16) []= (i int, value i16) {
	if i < 0 || i >= 16 {
