pub fn (v I16x16) max() i16 {
	return v.values[v.max_element()]
}

// dot multiplies corresponding lanes and adds the products, wrapping on overflow.
pub fn (a I16x16) dot(b I16x16) i16 {
	return (a * b).sum()
}

// to_u16x16 converts each lane to u16.
// It keeps the bits of each lane, so values wrap modulo 2^16.
@[direct_array_access]
pub fn (v I16x16) to_u16x16() U16x16 {
	mut r := U16x16{}
	for i in 0 .. 16 {
		r.values[i] = u16(v.values[i])
	}
	return r
}

// I16x32 holds 32 i16 lanes (512 bits).
pub struct I16x32 {
mut:
	values [32]i16
}

// splat_i16x32 returns a I16x32 with every lane set to value.
pub fn splat_i16x32(value i16) I16x32 {
	return I16x32{
		values: [32]i16{init: value}
	}
}

// from_array_i16x32 returns a I16x32 holding values in lane order.
pub fn from_array_i16x32(values [32]i16) I16x32 {
	return I16x32{
		values: values
	}
}

// load_i16x32 loads 32 values from the start of src.
// It returns an error if src has fewer than 32 values.
pub fn load_i16x32(src []i16) !I16x32 {
	if src.len < 32 {
		return error('simd.load_i16x32 needs at least 32 values')
	}
	return load_i16x32_at(src, 0)
}

// load_i16x32_part loads up to 32 values from src and zero-fills the remaining lanes.
// It returns an error if src has more than 32 values.
@[direct_array_access]
pub fn load_i16x32_part(src []i16) !I16x32 {
	if src.len > 32 {
		return error('simd.load_i16x32_part accepts at most 32 values')
	}
	mut r := I16x32{}
	for i in 0 .. src.len {
		r.values[i] = src[i]
	}
	return r
}

// load_i16x32_at loads 32 values starting at src[offset].
// It panics if offset is negative or fewer than 32 values follow it.
@[direct_array_access]
pub fn load_i16x32_at(src []i16, offset int) I16x32 {
	if offset < 0 || offset > src.len - 32 {
		range_panic('simd.load_i16x32_at', offset, src.len)
	}
	mut r := I16x32{}
	for i in 0 .. 32 {
		r.values[i] = src[offset + i]
	}
	return r
}

// select_i16x32 returns the lanes of a where mask is set and the lanes of b
// where it is clear.
@[direct_array_access]
pub fn select_i16x32(mask Mask16x32, a I16x32, b I16x32) I16x32 {
	mut r := I16x32{}
	$if @BACKEND == 'c' {
		native_select_i16(&mask.values[0], &a.values[0], &b.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			r.values[i] = if mask.values[i] != 0 { a.values[i] } else { b.values[i] }
		}
	}
	return r
}

// to_array returns the lanes in order.
pub fn (v I16x32) to_array() [32]i16 {
	return v.values
}

// [] returns lane i. It panics if i is out of range.
@[direct_array_access]
pub fn (v I16x32) [] (i int) i16 {
	if i < 0 || i >= 32 {
		lane_panic(i, 32)
	}
	return v.values[i]
}

// []= sets lane i to value. It panics if i is out of range.
@[direct_array_access]
pub fn (mut v I16x32) []= (i int, value i16) {
	if i < 0 || i >= 32 {
		lane_panic(i, 32)
	}
	v.values[i] = value
}

// store writes all 32 lanes to the start of dst.
// It returns an error if dst has fewer than 32 elements.
pub fn (v I16x32) store(mut dst []i16) ! {
	if dst.len < 32 {
		return error('simd.I16x32.store needs at least 32 values')
	}
	v.store_at(mut dst, 0)
}

// store_part writes one lane for each element of dst, up to 32 elements.
// It returns an error if dst has more than 32 elements.
@[direct_array_access]
pub fn (v I16x32) store_part(mut dst []i16) ! {
	if dst.len > 32 {
		return error('simd.I16x32.store_part accepts at most 32 values')
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&i16(dst.data) + 0, &v.values[0], dst.len * int(sizeof(i16))) }
	} $else {
		for i in 0 .. dst.len {
			dst[0 + i] = v.values[i]
		}
	}
}

// store_at writes all 32 lanes to dst, starting at dst[offset].
// It panics if offset is negative or fewer than 32 elements follow it.
@[direct_array_access]
pub fn (v I16x32) store_at(mut dst []i16, offset int) {
	if offset < 0 || offset > dst.len - 32 {
		range_panic('simd.I16x32.store_at', offset, dst.len)
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&i16(dst.data) + offset, &v.values[0], 32 * int(sizeof(i16))) }
	} $else {
		for i in 0 .. 32 {
			dst[offset + i] = v.values[i]
		}
	}
}

// + adds corresponding lanes, wrapping on overflow.
@[direct_array_access]
pub fn (a I16x32) + (b I16x32) I16x32 {
	mut r := I16x32{}
	$if @BACKEND == 'c' {
		native_add_i16(&a.values[0], &b.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			r.values[i] = i16(u32(a.values[i]) + u32(b.values[i]))
		}
	}
	return r
}

// - subtracts corresponding lanes, wrapping on overflow.
@[direct_array_access]
pub fn (a I16x32) - (b I16x32) I16x32 {
	mut r := I16x32{}
	$if @BACKEND == 'c' {
		native_sub_i16(&a.values[0], &b.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			r.values[i] = i16(u32(a.values[i]) - u32(b.values[i]))
		}
	}
	return r
}

// * multiplies corresponding lanes, wrapping on overflow.
@[direct_array_access]
pub fn (a I16x32) * (b I16x32) I16x32 {
	mut r := I16x32{}
	$if @BACKEND == 'c' {
		native_mul_i16(&a.values[0], &b.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			r.values[i] = i16(u32(a.values[i]) * u32(b.values[i]))
		}
	}
	return r
}

// / divides corresponding lanes, truncating toward zero.
// It panics if a lane of b is zero. min_i16 / -1 wraps to min_i16.
@[direct_array_access]
pub fn (a I16x32) / (b I16x32) I16x32 {
	mut r := I16x32{}
	for i in 0 .. 32 {
		r.values[i] = div_i16(a.values[i], b.values[i])
	}
	return r
}

// add returns a + b.
pub fn (a I16x32) add(b I16x32) I16x32 {
	return a + b
}

// sub returns a - b.
pub fn (a I16x32) sub(b I16x32) I16x32 {
	return a - b
}

// mul returns a * b.
pub fn (a I16x32) mul(b I16x32) I16x32 {
	return a * b
}

// div returns a / b.
pub fn (a I16x32) div(b I16x32) I16x32 {
	return a / b
}

// neg negates each lane, wrapping min_i16 to itself.
@[direct_array_access]
pub fn (a I16x32) neg() I16x32 {
	mut r := I16x32{}
	$if @BACKEND == 'c' {
		native_neg_i16(&a.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			r.values[i] = i16(u32(0) - u32(a.values[i]))
		}
	}
	return r
}

// abs returns the absolute value of each lane. min_i16 wraps to itself.
@[direct_array_access]
pub fn (a I16x32) abs() I16x32 {
	mut r := I16x32{}
	$if @BACKEND == 'c' {
		native_abs_i16(&a.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			x := a.values[i]
			r.values[i] = if x < 0 { i16(u32(0) - u32(x)) } else { x }
		}
	}
	return r
}

// minimum returns the smaller of each pair of lanes.
@[direct_array_access]
pub fn (a I16x32) minimum(b I16x32) I16x32 {
	mut r := I16x32{}
	$if @BACKEND == 'c' {
		native_min_i16(&a.values[0], &b.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			x := a.values[i]
			y := b.values[i]
			r.values[i] = if y < x { y } else { x }
		}
	}
	return r
}

// maximum returns the larger of each pair of lanes.
@[direct_array_access]
pub fn (a I16x32) maximum(b I16x32) I16x32 {
	mut r := I16x32{}
	$if @BACKEND == 'c' {
		native_max_i16(&a.values[0], &b.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			x := a.values[i]
			y := b.values[i]
			r.values[i] = if y > x { y } else { x }
		}
	}
	return r
}

// eq returns a mask of the lanes where a is equal to b.
@[direct_array_access]
pub fn (a I16x32) eq(b I16x32) Mask16x32 {
	mut r := Mask16x32{}
	$if @BACKEND == 'c' {
		native_eq_i16(&a.values[0], &b.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			if a.values[i] == b.values[i] {
				r.values[i] = -1
			}
		}
	}
	return r
}

// ne returns a mask of the lanes where a is not equal to b.
@[direct_array_access]
pub fn (a I16x32) ne(b I16x32) Mask16x32 {
	mut r := Mask16x32{}
	$if @BACKEND == 'c' {
		native_ne_i16(&a.values[0], &b.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			if a.values[i] != b.values[i] {
				r.values[i] = -1
			}
		}
	}
	return r
}

// lt returns a mask of the lanes where a is less than b.
@[direct_array_access]
pub fn (a I16x32) lt(b I16x32) Mask16x32 {
	mut r := Mask16x32{}
	$if @BACKEND == 'c' {
		native_lt_i16(&a.values[0], &b.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			if a.values[i] < b.values[i] {
				r.values[i] = -1
			}
		}
	}
	return r
}

// le returns a mask of the lanes where a is less than or equal to b.
@[direct_array_access]
pub fn (a I16x32) le(b I16x32) Mask16x32 {
	mut r := Mask16x32{}
	$if @BACKEND == 'c' {
		native_le_i16(&a.values[0], &b.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			if a.values[i] <= b.values[i] {
				r.values[i] = -1
			}
		}
	}
	return r
}

// gt returns a mask of the lanes where a is greater than b.
pub fn (a I16x32) gt(b I16x32) Mask16x32 {
	return b.lt(a)
}

// ge returns a mask of the lanes where a is greater than or equal to b.
pub fn (a I16x32) ge(b I16x32) Mask16x32 {
	return b.le(a)
}

// and returns the bitwise AND of corresponding lanes.
@[direct_array_access]
pub fn (a I16x32) and(b I16x32) I16x32 {
	mut r := I16x32{}
	$if @BACKEND == 'c' {
		native_and_i16(&a.values[0], &b.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			r.values[i] = a.values[i] & b.values[i]
		}
	}
	return r
}

// or returns the bitwise OR of corresponding lanes.
@[direct_array_access]
pub fn (a I16x32) or(b I16x32) I16x32 {
	mut r := I16x32{}
	$if @BACKEND == 'c' {
		native_or_i16(&a.values[0], &b.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			r.values[i] = a.values[i] | b.values[i]
		}
	}
	return r
}

// xor returns the bitwise XOR of corresponding lanes.
@[direct_array_access]
pub fn (a I16x32) xor(b I16x32) I16x32 {
	mut r := I16x32{}
	$if @BACKEND == 'c' {
		native_xor_i16(&a.values[0], &b.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			r.values[i] = a.values[i] ^ b.values[i]
		}
	}
	return r
}

// not returns the bitwise complement of each lane.
@[direct_array_access]
pub fn (a I16x32) not() I16x32 {
	mut r := I16x32{}
	$if @BACKEND == 'c' {
		native_not_i16(&a.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			r.values[i] = ~a.values[i]
		}
	}
	return r
}

// shl shifts each lane left by count bits.
// A count of 16 or more shifts every bit out and returns zero lanes.
@[direct_array_access]
pub fn (a I16x32) shl(count u32) I16x32 {
	if count >= 16 {
		return I16x32{}
	}
	mut r := I16x32{}
	$if @BACKEND == 'c' {
		native_shl_i16(&a.values[0], count, &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			r.values[i] = i16(u32(a.values[i]) << count)
		}
	}
	return r
}

// shr shifts each lane right by count bits.
// The shift is arithmetic: it copies the sign bit, and a count of 16 or
// more fills each lane with its sign bit.
@[direct_array_access]
pub fn (a I16x32) shr(count u32) I16x32 {
	c := if count >= 16 { u32(15) } else { count }
	mut r := I16x32{}
	$if @BACKEND == 'c' {
		native_shr_i16(&a.values[0], c, &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			r.values[i] = a.values[i] >> c
		}
	}
	return r
}

// sum adds the lanes, wrapping on overflow.
@[direct_array_access]
pub fn (v I16x32) sum() i16 {
	mut acc := u32(0)
	for i in 0 .. 32 {
		acc += u32(v.values[i])
	}
	return i16(acc)
}

// min_element returns the index of the first lane holding the smallest value.
@[direct_array_access]
pub fn (v I16x32) min_element() int {
	mut best := 0
	for i in 1 .. 32 {
		if v.values[i] < v.values[best] {
			best = i
		}
	}
	return best
}

// min returns the smallest lane value, the lane at index min_element().
@[direct_array_access]
pub fn (v I16x32) min() i16 {
	return v.values[v.min_element()]
}

// max_element returns the index of the first lane holding the largest value.
@[direct_array_access]
pub fn (v I16x32) max_element() int {
	mut best := 0
	for i in 1 .. 32 {
		if v.values[i] > v.values[best] {
			best = i
		}
	}
	return best
}

// max returns the largest lane value, the lane at index max_element().
@[direct_array_access]
pub fn (v I16x32) max() i16 {
	return v.values[v.max_element()]
}

// dot multiplies corresponding lanes and adds the products, wrapping on overflow.
pub fn (a I16x32) dot(b I16x32) i16 {
	return (a * b).sum()
}

// to_u16x32 converts each lane to u16.
// It keeps the bits of each lane, so values wrap modulo 2^16.
@[direct_array_access]
pub fn (v I16x32) to_u16x32() U16x32 {
	mut r := U16x32{}
	for i in 0 .. 32 {
		r.values[i] = u16(v.values[i])
	}
	return r
}

