// neg negates each lane, wrapping min_i32 to itself.
@[direct_array_access]
pub fn (a I32x2) neg() I32x2 {
	mut r := I32x2{}
	$if @BACKEND == 'c' {
		native_neg_i32(&a.values[0], &r.values[0], 2)
	} $else {
		for i in 0 .. 2 {
			r.values[i] = i32(u32(0) - u32(a.values[i]))
		}
	}
	return r
}

// abs returns the absolute value of each lane. min_i32 wraps to itself.
@[direct_array_access]
pub fn (a I32x2) abs() I32x2 {
	mut r := I32x2{}
	$if @BACKEND == 'c' {
		native_abs_i32(&a.values[0], &r.values[0], 2)
	} $else {
		for i in 0 .. 2 {
			x := a.values[i]
			r.values[i] = if x < 0 { i32(u32(0) - u32(x)) } else { x }
		}
	}
	return r
}

// minimum returns the smaller of each pair of lanes.
@[direct_array_access]
pub fn (a I32x2) minimum(b I32x2) I32x2 {
