// shl shifts each lane left by count bits.
// A count of 32 or more shifts every bit out and returns zero lanes.
@[direct_array_access]
pub fn (a I32x2) shl(count u32) I32x2 {
	if count >= 32 {
		return I32x2{}
	}
	mut r := I32x2{}
	$if @BACKEND == 'c' {
		native_shl_i32(&a.values[0], count, &r.values[0], 2)
	} $else {
		for i in 0 .. 2 {
			r.values[i] = i32(u32(a.values[i]) << count)
		}
	}
	return r
}

// shr shifts each lane right by count bits.
// The shift is arithmetic: it copies the sign bit, and a count of 32 or
// more fills each lane with its sign bit.
@[direct_array_access]
pub fn (a I32x2) shr(count u32) I32x2 {
	c := if count >= 32 { u32(31) } else { count }
	mut r := I32x2{}
	$if @BACKEND == 'c' {
		native_shr_i32(&a.values[0], c, &r.values[0], 2)
	} $else {
		for i in 0 .. 2 {
			r.values[i] = a.values[i] >> c
		}
	}
	return r
}

// sum adds the lanes, wrapping on overflow.
@[direct_array_access]
pub fn (v I32x2) sum() i32 {
	mut acc := u32(0)
	for i in 0 .. 2 {
		acc += u32(v.values[i])
	}
	return i32(acc)
}

// min_element returns the index of the first lane holding the smallest value.
@[direct_array_access]
pub fn (v I32x2) min_element() int {
	mut best := 0
	for i in 1 .. 2 {
		if v.values[i] < v.values[best] {
			best = i
		}
	}
	return best
}

// min returns the smallest lane value, the lane at index min_element().
@[direct_array_access]
pub fn (v I32x2) min() i32 {
	return v.values[v.min_element()]
}

// max_element returns the index of the first lane holding the largest value.
@[direct_array_access]
pub fn (v I32x2) max_element() int {
	mut best := 0
	for i in 1 .. 2 {
		if v.values[i] > v.values[best] {
			best = i
		}
	}
	return best
}

// max returns the largest lane value, the lane at index max_element().
@[direct_array_access]
pub fn (v I32x2) max() i32 {
	return v.values[v.max_element()]
}

// dot multiplies corresponding lanes and adds the products, wrapping on overflow.
pub fn (a I32x2) dot(b I32x2) i32 {
	return (a * b).sum()
}

// to_f32x2 converts each lane to f32.
// It rounds to the nearest f32 value.
@[direct_array_access]
pub fn (v I32x2) to_f32x2() F32x2 {
	mut r := F32x2{}
	for i in 0 .. 2 {
		r.values[i] = f32(v.values[i])
	}
	return r
}

// to_u32x2 converts each lane to u32.
// It keeps the bits of each lane, so values wrap modulo 2^32.
@[direct_array_access]
pub fn (v I32x2) to_u32x2() U32x2 {
	mut r := U32x2{}
	for i in 0 .. 2 {
		r.values[i] = u32(v.values[i])
	}
	return r
}

// I32x4 holds 4 i32 lanes (128 bits).
pub struct I32x4 {
mut:
	values [4]i32
}

// i32x4 creates a I32x4 from its lanes in lane order.
pub fn i32x4(a i32, b i32, c i32, d i32) I32x4 {
	return I32x4{
		values: [a, b, c, d]!
	}
}

// splat_i32x4 returns a I32x4 with every lane set to value.
pub fn splat_i32x4(value i32) I32x4 {
	return I32x4{
		values: [4]i32{init: value}
	}
}

// from_array_i32x4 returns a I32x4 holding values in lane order.
pub fn from_array_i32x4(values [4]i32) I32x4 {
	return I32x4{
		values: values
	}
}

// load_i32x4 loads 4 values from the start of src.
// It returns an error if src has fewer than 4 values.
pub fn load_i32x4(src []i32) !I32x4 {
	if src.len < 4 {
		return error('simd.load_i32x4 needs at least 4 values')
	}
	return load_i32x4_at(src, 0)
}

// load_i32x4_part loads up to 4 values from src and zero-fills the remaining lanes.
// It returns an error if src has more than 4 values.
@[direct_array_access]
pub fn load_i32x4_part(src []i32) !I32x4 {
	if src.len > 4 {
		return error('simd.load_i32x4_part accepts at most 4 values')
	}
	mut r := I32x4{}
	for i in 0 .. src.len {
		r.values[i] = src[i]
	}
	return r
}

// load_i32x4_at loads 4 values starting at src[offset].
// It panics if offset is negative or fewer than 4 values follow it.
@[direct_array_access]
pub fn load_i32x4_at(src []i32, offset int) I32x4 {
	if offset < 0 || offset > src.len - 4 {
		range_panic('simd.load_i32x4_at', offset, src.len)
	}
	mut r := I32x4{}
	for i in 0 .. 4 {
		r.values[i] = src[offset + i]
	}
	return r
}

// select_i32x4 returns the lanes of a where mask is set and the lanes of b
// where it is clear.
@[direct_array_access]
pub fn select_i32x4(mask Mask32x4, a I32x4, b I32x4) I32x4 {
	mut r := I32x4{}
	$if @BACKEND == 'c' {
		native_select_i32(&mask.values[0], &a.values[0], &b.values[0], &r.values[0], 4)
	} $else {
		for i in 0 .. 4 {
			r.values[i] = if mask.values[i] != 0 { a.values[i] } else { b.values[i] }
		}
	}
	return r
}

// to_array returns the lanes in order.
pub fn (v I32x4) to_array() [4]i32 {
	return v.values
}

// [] returns lane i. It panics if i is out of range.
@[direct_array_access]
pub fn (v I32x4) [] (i int) i32 {
	if i < 0 || i >= 4 {
		lane_panic(i, 4)
	}
	return v.values[i]
}

// []= sets lane i to value. It panics if i is out of range.
@[direct_array_access]
pub fn (mut v I32x4) []= (i int, value i32) {
	if i < 0 || i >= 4 {
		lane_panic(i, 4)
	}
	v.values[i] = value
}

// store writes all 4 lanes to the start of dst.
// It returns an error if dst has fewer than 4 elements.
pub fn (v I32x4) store(mut dst []i32) ! {
	if dst.len < 4 {
		return error('simd.I32x4.store needs at least 4 values')
	}
	v.store_at(mut dst, 0)
}

// store_part writes one lane for each element of dst, up to 4 elements.
// It returns an error if dst has more than 4 elements.
@[direct_array_access]
pub fn (v I32x4) store_part(mut dst []i32) ! {
	if dst.len > 4 {
		return error('simd.I32x4.store_part accepts at most 4 values')
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&i32(dst.data) + 0, &v.values[0], dst.len * int(sizeof(i32))) }
	} $else {
		for i in 0 .. dst.len {
			dst[0 + i] = v.values[i]
		}
	}
}

// store_at writes all 4 lanes to dst, starting at dst[offset].
// It panics if offset is negative or fewer than 4 elements follow it.
@[direct_array_access]
pub fn (v I32x4) store_at(mut dst []i32, offset int) {
	if offset < 0 || offset > dst.len - 4 {
		range_panic('simd.I32x4.store_at', offset, dst.len)
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&i32(dst.data) + offset, &v.values[0], 4 * int(sizeof(i32))) }
	} $else {
		for i in 0 .. 4 {
			dst[offset + i] = v.values[i]
		}
	}
}

