pub fn (v I32x16) store_part(mut dst []i32) ! {
	if dst.len > 16 {
		return error('simd.I32x16.store_part accepts at most 16 values')
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&i32(dst.data) + 0, &v.values[0], dst.len * int(sizeof(i32))) }
	} $else {
		for i in 0 .. dst.len {
			dst[0 + i] = v.values[i]
		}
	}
}

// store_at writes all 16 lanes to dst, starting at dst[offset].
// It panics if offset is negative or fewer than 16 elements follow it.
@[direct_array_access]
pub fn (v I32x16) store_at(mut dst []i32, offset int) {
	if offset < 0 || offset > dst.len - 16 {
		range_panic('simd.I32x16.store_at', offset, dst.len)
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&i32(dst.data) + offset, &v.values[0], 16 * int(sizeof(i32))) }
	} $else {
		for i in 0 .. 16 {
			dst[offset + i] = v.values[i]
		}
	}
}

