	return r
}

// to_u32x16 converts each lane to u32.
// It keeps the bits of each lane, so values wrap modulo 2^32.
@[direct_array_access]
pub fn (v I32x16) to_u32x16() U32x16 {
	mut r := U32x16{}
	for i in 0 .. 16 {
