	return r
}

// I64x2 holds 2 i64 lanes (128 bits).
pub struct I64x2 {
mut:
	values [2]i64
}

// i64x2 creates a I64x2 from its lanes in lane order.
pub fn i64x2(a i64, b i64) I64x2 {
	return I64x2{
		values: [a, b]!
	}
}

// splat_i64x2 returns a I64x2 with every lane set to value.
pub fn splat_i64x2(value i64) I64x2 {
	return I64x2{
		values: [2]i64{init: value}
	}
}

// from_array_i64x2 returns a I64x2 holding values in lane order.
pub fn from_array_i64x2(values [2]i64) I64x2 {
	return I64x2{
		values: values
	}
}

// load_i64x2 loads 2 values from the start of src.
// It returns an error if src has fewer than 2 values.
pub fn load_i64x2(src []i64) !I64x2 {
	if src.len < 2 {
		return error('simd.load_i64x2 needs at least 2 values')
	}
	return load_i64x2_at(src, 0)
}

// load_i64x2_part loads up to 2 values from src and zero-fills the remaining lanes.
// It returns an error if src has more than 2 values.
@[direct_array_access]
pub fn load_i64x2_part(src []i64) !I64x2 {
	if src.len > 2 {
		return error('simd.load_i64x2_part accepts at most 2 values')
	}
	mut r := I64x2{}
	for i in 0 .. src.len {
		r.values[i] = src[i]
	}
	return r
}

// load_i64x2_at loads 2 values starting at src[offset].
// It panics if offset is negative or fewer than 2 values follow it.
@[direct_array_access]
pub fn load_i64x2_at(src []i64, offset int) I64x2 {
	if offset < 0 || offset > src.len - 2 {
		range_panic('simd.load_i64x2_at', offset, src.len)
	}
	mut r := I64x2{}
	for i in 0 .. 2 {
		r.values[i] = src[offset + i]
	}
	return r
}

// select_i64x2 returns the lanes of a where mask is set and the lanes of b
// where it is clear.
@[direct_array_access]
pub fn select_i64x2(mask Mask64x2, a I64x2, b I64x2) I64x2 {
	mut r := I64x2{}
	$if @BACKEND == 'c' {
		native_select_i64(&mask.values[0], &a.values[0], &b.values[0], &r.values[0], 2)
	} $else {
		for i in 0 .. 2 {
			r.values[i] = if mask.values[i] != 0 { a.values[i] } else { b.values[i] }
		}
	}
	return r
}

// to_array returns the lanes in order.
pub fn (v I64x2) to_array() [2]i64 {
	return v.values
}

// [] returns lane i. It panics if i is out of range.
@[direct_array_access]
pub fn (v I64x2) [] (i int) i64 {
	if i < 0 || i >= 2 {
		lane_panic(i, 2)
	}
	return v.values[i]
}

// []= sets lane i to value. It panics if i is out of range.
@[direct_array_access]
pub fn (mut v I64x2) []= (i int, value i64) {
	if i < 0 || i >= 2 {
		lane_panic(i, 2)
	}
	v.values[i] = value
}

// store writes all 2 lanes to the start of dst.
// It returns an error if dst has fewer than 2 elements.
pub fn (v I64x2) store(mut dst []i64) ! {
	if dst.len < 2 {
		return error('simd.I64x2.store needs at least 2 values')
	}
	v.store_at(mut dst, 0)
}

// store_part writes one lane for each element of dst, up to 2 elements.
// It returns an error if dst has more than 2 elements.
@[direct_array_access]
pub fn (v I64x2) store_part(mut dst []i64) ! {
	if dst.len > 2 {
		return error('simd.I64x2.store_part accepts at most 2 values')
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&i64(dst.data) + 0, &v.values[0], dst.len * int(sizeof(i64))) }
	} $else {
		for i in 0 .. dst.len {
			dst[0 + i] = v.values[i]
		}
	}
