// from_array_i64x8 returns a I64x8 holding values in lane order.
pub fn from_array_i64x8(values [8]i64) I64x8 {
	return I64x8{
		values: values
	}
}

// load_i64x8 loads 8 values from the start of src.
// It returns an error if src has fewer than 8 values.
pub fn load_i64x8(src []i64) !I64x8 {
	if src.len < 8 {
		return error('simd.load_i64x8 needs at least 8 values')
	}
	return load_i64x8_at(src, 0)
}

// load_i64x8_part loads up to 8 values from src and zero-fills the remaining lanes.
// It returns an error if src has more than 8 values.
@[direct_array_access]
pub fn load_i64x8_part(src []i64) !I64x8 {
	if src.len > 8 {
		return error('simd.load_i64x8_part accepts at most 8 values')
	}
	mut r := I64x8{}
	for i in 0 .. src.len {
		r.values[i] = src[i]
	}
	return r
}

// load_i64x8_at loads 8 values starting at src[offset].
// It panics if offset is negative or fewer than 8 values follow it.
@[direct_array_access]
pub fn load_i64x8_at(src []i64, offset int) I64x8 {
	if offset < 0 || offset > src.len - 8 {
		range_panic('simd.load_i64x8_at', offset, src.len)
	}
	mut r := I64x8{}
	for i in 0 .. 8 {
		r.values[i] = src[offset + i]
	}
	return r
}

// select_i64x8 returns the lanes of a where mask is set and the lanes of b
// where it is clear.
@[direct_array_access]
pub fn select_i64x8(mask Mask64x8, a I64x8, b I64x8) I64x8 {
	mut r := I64x8{}
	$if @BACKEND == 'c' {
		native_select_i64(&mask.values[0], &a.values[0], &b.values[0], &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			r.values[i] = if mask.values[i] != 0 { a.values[i] } else { b.values[i] }
		}
	}
	return r
}

// to_array returns the lanes in order.
pub fn (v I64x8) to_array() [8]i64 {
	return v.values
}

// [] returns lane i. It panics if i is out of range.
@[direct_array_access]
pub fn (v I64x8) [] (i int) i64 {
	if i < 0 || i >= 8 {
		lane_panic(i, 8)
	}
	return v.values[i]
}

// []= sets lane i to value. It panics if i is out of range.
@[direct_array_access]
pub fn (mut v I64x8) []= (i int, value i64) {
	if i < 0 || i >= 8 {
		lane_panic(i, 8)
	}
	v.values[i] = value
}

// store writes all 8 lanes to the start of dst.
// It returns an error if dst has fewer than 8 elements.
pub fn (v I64x8) store(mut dst []i64) ! {
	if dst.len < 8 {
		return error('simd.I64x8.store needs at least 8 values')
	}
	v.store_at(mut dst, 0)
}

// store_part writes one lane for each element of dst, up to 8 elements.
// It returns an error if dst has more than 8 elements.
@[direct_array_access]
pub fn (v I64x8) store_part(mut dst []i64) ! {
	if dst.len > 8 {
		return error('simd.I64x8.store_part accepts at most 8 values')
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&i64(dst.data) + 0, &v.values[0], dst.len * int(sizeof(i64))) }
	} $else {
		for i in 0 .. dst.len {
			dst[0 + i] = v.values[i]
		}
	}
}

// store_at writes all 8 lanes to dst, starting at dst[offset].
// It panics if offset is negative or fewer than 8 elements follow it.
@[direct_array_access]
pub fn (v I64x8) store_at(mut dst []i64, offset int) {
	if offset < 0 || offset > dst.len - 8 {
		range_panic('simd.I64x8.store_at', offset, dst.len)
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&i64(dst.data) + offset, &v.values[0], 8 * int(sizeof(i64))) }
	} $else {
		for i in 0 .. 8 {
			dst[offset + i] = v.values[i]
		}
	}
}

// + adds corresponding lanes, wrapping on overflow.
@[direct_array_access]
pub fn (a I64x8) + (b I64x8) I64x8 {
	mut r := I64x8{}
	$if @BACKEND == 'c' {
		native_add_i64(&a.values[0], &b.values[0], &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			r.values[i] = i64(u64(a.values[i]) + u64(b.values[i]))
		}
	}
	return r
}

// - subtracts corresponding lanes, wrapping on overflow.
@[direct_array_access]
pub fn (a I64x8) - (b I64x8) I64x8 {
	mut r := I64x8{}
	$if @BACKEND == 'c' {
		native_sub_i64(&a.values[0], &b.values[0], &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			r.values[i] = i64(u64(a.values[i]) - u64(b.values[i]))
		}
	}
	return r
}

// * multiplies corresponding lanes, wrapping on overflow.
@[direct_array_access]
pub fn (a I64x8) * (b I64x8) I64x8 {
	mut r := I64x8{}
	$if @BACKEND == 'c' {
		native_mul_i64(&a.values[0], &b.values[0], &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			r.values[i] = i64(u64(a.values[i]) * u64(b.values[i]))
		}
	}
	return r
}

// / divides corresponding lanes, truncating toward zero.
// It panics if a lane of b is zero. min_i64 / -1 wraps to min_i64.
@[direct_array_access]
pub fn (a I64x8) / (b I64x8) I64x8 {
	mut r := I64x8{}
	for i in 0 .. 8 {
		r.values[i] = div_i64(a.values[i], b.values[i])
	}
	return r
}

// add returns a + b.
pub fn (a I64x8) add(b I64x8) I64x8 {
	return a + b
}

// sub returns a - b.
pub fn (a I64x8) sub(b I64x8) I64x8 {
	return a - b
}

// mul returns a * b.
pub fn (a I64x8) mul(b I64x8) I64x8 {
	return a * b
}

// div returns a / b.
pub fn (a I64x8) div(b I64x8) I64x8 {
	return a / b
}

// neg negates each lane, wrapping min_i64 to itself.
@[direct_array_access]
pub fn (a I64x8) neg() I64x8 {
	mut r := I64x8{}
	$if @BACKEND == 'c' {
		native_neg_i64(&a.values[0], &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			r.values[i] = i64(u64(0) - u64(a.values[i]))
		}
	}
	return r
}

// abs returns the absolute value of each lane. min_i64 wraps to itself.
@[direct_array_access]
pub fn (a I64x8) abs() I64x8 {
	mut r := I64x8{}
	$if @BACKEND == 'c' {
		native_abs_i64(&a.values[0], &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			x := a.values[i]
			r.values[i] = if x < 0 { i64(u64(0) - u64(x)) } else { x }
		}
	}
	return r
}

// minimum returns the smaller of each pair of lanes.
@[direct_array_access]
pub fn (a I64x8) minimum(b I64x8) I64x8 {
	mut r := I64x8{}
	$if @BACKEND == 'c' {
		native_min_i64(&a.values[0], &b.values[0], &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			x := a.values[i]
			y := b.values[i]
			r.values[i] = if y < x { y } else { x }
		}
	}
	return r
}

// maximum returns the larger of each pair of lanes.
@[direct_array_access]
pub fn (a I64x8) maximum(b I64x8) I64x8 {
	mut r := I64x8{}
	$if @BACKEND == 'c' {
		native_max_i64(&a.values[0], &b.values[0], &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			x := a.values[i]
			y := b.values[i]
			r.values[i] = if y > x { y } else { x }
		}
	}
	return r
}

// eq returns a mask of the lanes where a is equal to b.
@[direct_array_access]
pub fn (a I64x8) eq(b I64x8) Mask64x8 {
	mut r := Mask64x8{}
	$if @BACKEND == 'c' {
		native_eq_i64(&a.values[0], &b.values[0], &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			if a.values[i] == b.values[i] {
				r.values[i] = -1
			}
		}
	}
	return r
}

// ne returns a mask of the lanes where a is not equal to b.
@[direct_array_access]
pub fn (a I64x8) ne(b I64x8) Mask64x8 {
	mut r := Mask64x8{}
	$if @BACKEND == 'c' {
