				r.values[i] = -1
			}
		}
	}
	return r
}

// lt returns a mask of the lanes where a is less than b.
@[direct_array_access]
pub fn (a I64x8) lt(b I64x8) Mask64x8 {
	mut r := Mask64x8{}
	$if @BACKEND == 'c' {
		native_lt_i64(&a.values[0], &b.values[0], &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			if a.values[i] < b.values[i] {
				r.values[i] = -1
			}
		}
	}
	return r
}

// le returns a mask of the lanes where a is less than or equal to b.
@[direct_array_access]
pub fn (a I64x8) le(b I64x8) Mask64x8 {
	mut r := Mask64x8{}
	$if @BACKEND == 'c' {
		native_le_i64(&a.values[0], &b.values[0], &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			if a.values[i] <= b.values[i] {
				r.values[i] = -1
			}
		}
	}
	return r
}

// gt returns a mask of the lanes where a is greater than b.
pub fn (a I64x8) gt(b I64x8) Mask64x8 {
	return b.lt(a)
}

// ge returns a mask of the lanes where a is greater than or equal to b.
pub fn (a I64x8) ge(b I64x8) Mask64x8 {
	return b.le(a)
}

// and returns the bitwise AND of corresponding lanes.
@[direct_array_access]
pub fn (a I64x8) and(b I64x8) I64x8 {
	mut r := I64x8{}
	$if @BACKEND == 'c' {
		native_and_i64(&a.values[0], &b.values[0], &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			r.values[i] = a.values[i] & b.values[i]
		}
	}
	return r
}

// or returns the bitwise OR of corresponding lanes.
@[direct_array_access]
pub fn (a I64x8) or(b I64x8) I64x8 {
	mut r := I64x8{}
	$if @BACKEND == 'c' {
		native_or_i64(&a.values[0], &b.values[0], &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			r.values[i] = a.values[i] | b.values[i]
		}
	}
	return r
}

// xor returns the bitwise XOR of corresponding lanes.
@[direct_array_access]
pub fn (a I64x8) xor(b I64x8) I64x8 {
	mut r := I64x8{}
	$if @BACKEND == 'c' {
		native_xor_i64(&a.values[0], &b.values[0], &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			r.values[i] = a.values[i] ^ b.values[i]
		}
	}
	return r
}

// not returns the bitwise complement of each lane.
@[direct_array_access]
pub fn (a I64x8) not() I64x8 {
	mut r := I64x8{}
	$if @BACKEND == 'c' {
		native_not_i64(&a.values[0], &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			r.values[i] = ~a.values[i]
		}
	}
	return r
}

// shl shifts each lane left by count bits.
// A count of 64 or more shifts every bit out and returns zero lanes.
@[direct_array_access]
pub fn (a I64x8) shl(count u32) I64x8 {
	if count >= 64 {
		return I64x8{}
	}
	mut r := I64x8{}
	$if @BACKEND == 'c' {
		native_shl_i64(&a.values[0], count, &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			r.values[i] = i64(u64(a.values[i]) << count)
		}
	}
	return r
}

// shr shifts each lane right by count bits.
// The shift is arithmetic: it copies the sign bit, and a count of 64 or
// more fills each lane with its sign bit.
@[direct_array_access]
pub fn (a I64x8) shr(count u32) I64x8 {
	c := if count >= 64 { u32(63) } else { count }
	mut r := I64x8{}
	$if @BACKEND == 'c' {
		native_shr_i64(&a.values[0], c, &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			r.values[i] = a.values[i] >> c
		}
	}
	return r
}

// sum adds the lanes, wrapping on overflow.
@[direct_array_access]
pub fn (v I64x8) sum() i64 {
	mut acc := u64(0)
	for i in 0 .. 8 {
		acc += u64(v.values[i])
	}
	return i64(acc)
}

// min_element returns the index of the first lane holding the smallest value.
@[direct_array_access]
pub fn (v I64x8) min_element() int {
	mut best := 0
	for i in 1 .. 8 {
		if v.values[i] < v.values[best] {
			best = i
		}
	}
	return best
}

// min returns the smallest lane value, the lane at index min_element().
@[direct_array_access]
pub fn (v I64x8) min() i64 {
	return v.values[v.min_element()]
}

// max_element returns the index of the first lane holding the largest value.
@[direct_array_access]
pub fn (v I64x8) max_element() int {
	mut best := 0
	for i in 1 .. 8 {
		if v.values[i] > v.values[best] {
			best = i
		}
	}
	return best
}

// max returns the largest lane value, the lane at index max_element().
@[direct_array_access]
pub fn (v I64x8) max() i64 {
	return v.values[v.max_element()]
}

// dot multiplies corresponding lanes and adds the products, wrapping on overflow.
pub fn (a I64x8) dot(b I64x8) i64 {
	return (a * b).sum()
}

// to_f64x8 converts each lane to f64.
// It rounds to the nearest f64 value.
@[direct_array_access]
pub fn (v I64x8) to_f64x8() F64x8 {
	mut r := F64x8{}
	for i in 0 .. 8 {
		r.values[i] = f64(v.values[i])
	}
	return r
}

// to_u64x8 converts each lane to u64.
// It keeps the bits of each lane, so values wrap modulo 2^64.
@[direct_array_access]
pub fn (v I64x8) to_u64x8() U64x8 {
	mut r := U64x8{}
	for i in 0 .. 8 {
		r.values[i] = u64(v.values[i])
	}
	return r
}

// U8x8 holds 8 u8 lanes (64 bits).
pub struct U8x8 {
mut:
	values [8]u8
}

// u8x8 creates a U8x8 from its lanes in lane order.
pub fn u8x8(a u8, b u8, c u8, d u8, e u8, f u8, g u8, h u8) U8x8 {
