	}
}

// load_u8x16 loads 16 values from the start of src.
// It returns an error if src has fewer than 16 values.
pub fn load_u8x16(src []u8) !U8x16 {
	if src.len < 16 {
		return error('simd.load_u8x16 needs at least 16 values')
	}
	return load_u8x16_at(src, 0)
}

// load_u8x16_part loads up to 16 values from src and zero-fills the remaining lanes.
// It returns an error if src has more than 16 values.
@[direct_array_access]
pub fn load_u8x16_part(src []u8) !U8x16 {
	if src.len > 16 {
		return error('simd.load_u8x16_part accepts at most 16 values')
	}
	mut r := U8x16{}
	for i in 0 .. src.len {
		r.values[i] = src[i]
	}
	return r
}

// load_u8x16_at loads 16 values starting at src[offset].
// It panics if offset is negative or fewer than 16 values follow it.
@[direct_array_access]
pub fn load_u8x16_at(src []u8, offset int) U8x16 {
	if offset < 0 || offset > src.len - 16 {
		range_panic('simd.load_u8x16_at', offset, src.len)
	}
	mut r := U8x16{}
	for i in 0 .. 16 {
		r.values[i] = src[offset + i]
	}
	return r
}

// select_u8x16 returns the lanes of a where mask is set and the lanes of b
// where it is clear.
@[direct_array_access]
pub fn select_u8x16(mask Mask8x16, a U8x16, b U8x16) U8x16 {
	mut r := U8x16{}
	$if @BACKEND == 'c' {
		native_select_u8(&mask.values[0], &a.values[0], &b.values[0], &r.values[0], 16)
	} $else {
		for i in 0 .. 16 {
			r.values[i] = if mask.values[i] != 0 { a.values[i] } else { b.values[i] }
		}
	}
	return r
}

