// [] returns lane i. It panics if i is out of range.
@[direct_array_access]
pub fn (v U8x16) [] (i int) u8 {
	if i < 0 || i >= 16 {
		lane_panic(i, 16)
	}
	return v.values[i]
}

// []= sets lane i to value. It panics if i is out of range.
@[direct_array_access]
pub fn (mut v U8x16) []= (i int, value u8) {
	if i < 0 || i >= 16 {
		lane_panic(i, 16)
	}
	v.values[i] = value
}

// store writes all 16 lanes to the start of dst.
// It returns an error if dst has fewer than 16 elements.
pub fn (v U8x16) store(mut dst []u8) ! {
	if dst.len < 16 {
		return error('simd.U8x16.store needs at least 16 values')
	}
	v.store_at(mut dst, 0)
}

// store_part writes one lane for each element of dst, up to 16 elements.
// It returns an error if dst has more than 16 elements.
@[direct_array_access]
pub fn (v U8x16) store_part(mut dst []u8) ! {
	if dst.len > 16 {
		return error('simd.U8x16.store_part accepts at most 16 values')
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&u8(dst.data) + 0, &v.values[0], dst.len * int(sizeof(u8))) }
	} $else {
		for i in 0 .. dst.len {
			dst[0 + i] = v.values[i]
		}
	}
}

// store_at writes all 16 lanes to dst, starting at dst[offset].
// It panics if offset is negative or fewer than 16 elements follow it.
@[direct_array_access]
pub fn (v U8x16) store_at(mut dst []u8, offset int) {
	if offset < 0 || offset > dst.len - 16 {
		range_panic('simd.U8x16.store_at', offset, dst.len)
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&u8(dst.data) + offset, &v.values[0], 16 * int(sizeof(u8))) }
	} $else {
		for i in 0 .. 16 {
			dst[offset + i] = v.values[i]
		}
	}
}

