		values: values
	}
}

// load_u8x32 loads 32 values from the start of src.
// It returns an error if src has fewer than 32 values.
pub fn load_u8x32(src []u8) !U8x32 {
	if src.len < 32 {
		return error('simd.load_u8x32 needs at least 32 values')
	}
	return load_u8x32_at(src, 0)
}

// load_u8x32_part loads up to 32 values from src and zero-fills the remaining lanes.
// It returns an error if src has more than 32 values.
@[direct_array_access]
pub fn load_u8x32_part(src []u8) !U8x32 {
	if src.len > 32 {
		return error('simd.load_u8x32_part accepts at most 32 values')
	}
	mut r := U8x32{}
	for i in 0 .. src.len {
		r.values[i] = src[i]
	}
	return r
}

// load_u8x32_at loads 32 values starting at src[offset].
// It panics if offset is negative or fewer than 32 values follow it.
@[direct_array_access]
pub fn load_u8x32_at(src []u8, offset int) U8x32 {
	if offset < 0 || offset > src.len - 32 {
		range_panic('simd.load_u8x32_at', offset, src.len)
	}
	mut r := U8x32{}
	for i in 0 .. 32 {
		r.values[i] = src[offset + i]
	}
	return r
}

// select_u8x32 returns the lanes of a where mask is set and the lanes of b
// where it is clear.
@[direct_array_access]
pub fn select_u8x32(mask Mask8x32, a U8x32, b U8x32) U8x32 {
	mut r := U8x32{}
	$if @BACKEND == 'c' {
		native_select_u8(&mask.values[0], &a.values[0], &b.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			r.values[i] = if mask.values[i] != 0 { a.values[i] } else { b.values[i] }
		}
	}
	return r
}

// to_array returns the lanes in order.
pub fn (v U8x32) to_array() [32]u8 {
	return v.values
}

// [] returns lane i. It panics if i is out of range.
@[direct_array_access]
pub fn (v U8x32) [] (i int) u8 {
	if i < 0 || i >= 32 {
		lane_panic(i, 32)
	}
	return v.values[i]
}

// []= sets lane i to value. It panics if i is out of range.
@[direct_array_access]
pub fn (mut v U8x32) []= (i int, value u8) {
