		lane_panic(i, 32)
	}
	v.values[i] = value
}

// store writes all 32 lanes to the start of dst.
// It returns an error if dst has fewer than 32 elements.
pub fn (v U8x32) store(mut dst []u8) ! {
	if dst.len < 32 {
		return error('simd.U8x32.store needs at least 32 values')
	}
	v.store_at(mut dst, 0)
}

// store_part writes one lane for each element of dst, up to 32 elements.
// It returns an error if dst has more than 32 elements.
@[direct_array_access]
pub fn (v U8x32) store_part(mut dst []u8) ! {
	if dst.len > 32 {
		return error('simd.U8x32.store_part accepts at most 32 values')
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&u8(dst.data) + 0, &v.values[0], dst.len * int(sizeof(u8))) }
	} $else {
		for i in 0 .. dst.len {
			dst[0 + i] = v.values[i]
		}
	}
}

// store_at writes all 32 lanes to dst, starting at dst[offset].
// It panics if offset is negative or fewer than 32 elements follow it.
@[direct_array_access]
pub fn (v U8x32) store_at(mut dst []u8, offset int) {
	if offset < 0 || offset > dst.len - 32 {
		range_panic('simd.U8x32.store_at', offset, dst.len)
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&u8(dst.data) + offset, &v.values[0], 32 * int(sizeof(u8))) }
	} $else {
		for i in 0 .. 32 {
			dst[offset + i] = v.values[i]
		}
	}
}

