// not returns the bitwise complement of each lane.
@[direct_array_access]
pub fn (a U8x32) not() U8x32 {
	mut r := U8x32{}
	$if @BACKEND == 'c' {
		native_not_u8(&a.values[0], &r.values[0], 32)
	} $else {
