// shl shifts each lane left by count bits.
// A count of 8 or more shifts every bit out and returns zero lanes.
@[direct_array_access]
pub fn (a U8x32) shl(count u32) U8x32 {
	if count >= 8 {
		return U8x32{}
	}
	mut r := U8x32{}
	$if @BACKEND == 'c' {
		native_shl_u8(&a.values[0], count, &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			r.values[i] = u8(u32(a.values[i]) << count)
		}
	}
	return r
}

// shr shifts each lane right by count bits.
// A count of 8 or more shifts every bit out and returns zero lanes.
@[direct_array_access]
pub fn (a U8x32) shr(count u32) U8x32 {
	if count >= 8 {
		return U8x32{}
	}
	mut r := U8x32{}
	$if @BACKEND == 'c' {
		native_shr_u8(&a.values[0], count, &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			r.values[i] = a.values[i] >> count
		}
	}
	return r
}

// sum adds the lanes, wrapping on overflow.
@[direct_array_access]
pub fn (v U8x32) sum() u8 {
	mut acc := u32(0)
	for i in 0 .. 32 {
		acc += u32(v.values[i])
	}
	return u8(acc)
}

// min_element returns the index of the first lane holding the smallest value.
@[direct_array_access]
pub fn (v U8x32) min_element() int {
	mut best := 0
	for i in 1 .. 32 {
		if v.values[i] < v.values[best] {
			best = i
		}
	}
	return best
}

// min returns the smallest lane value, the lane at index min_element().
@[direct_array_access]
pub fn (v U8x32) min() u8 {
	return v.values[v.min_element()]
}

// max_element returns the index of the first lane holding the largest value.
@[direct_array_access]
pub fn (v U8x32) max_element() int {
	mut best := 0
	for i in 1 .. 32 {
		if v.values[i] > v.values[best] {
			best = i
		}
	}
	return best
}

// max returns the largest lane value, the lane at index max_element().
@[direct_array_access]
pub fn (v U8x32) max() u8 {
	return v.values[v.max_element()]
}

// dot multiplies corresponding lanes and adds the products, wrapping on overflow.
pub fn (a U8x32) dot(b U8x32) u8 {
	return (a * b).sum()
}

// to_i8x32 converts each lane to i8.
// It keeps the bits of each lane, so values wrap modulo 2^8.
@[direct_array_access]
pub fn (v U8x32) to_i8x32() I8x32 {
	mut r := I8x32{}
	for i in 0 .. 32 {
		r.values[i] = i8(v.values[i])
	}
	return r
}

