// load_u16x4 loads 4 values from the start of src.
// It returns an error if src has fewer than 4 values.
pub fn load_u16x4(src []u16) !U16x4 {
	if src.len < 4 {
		return error('simd.load_u16x4 needs at least 4 values')
	}
	return load_u16x4_at(src, 0)
}

// load_u16x4_part loads up to 4 values from src and zero-fills the remaining lanes.
// It returns an error if src has more than 4 values.
@[direct_array_access]
pub fn load_u16x4_part(src []u16) !U16x4 {
	if src.len > 4 {
		return error('simd.load_u16x4_part accepts at most 4 values')
	}
	mut r := U16x4{}
	for i in 0 .. src.len {
		r.values[i] = src[i]
	}
	return r
}

// load_u16x4_at loads 4 values starting at src[offset].
// It panics if offset is negative or fewer than 4 values follow it.
@[direct_array_access]
pub fn load_u16x4_at(src []u16, offset int) U16x4 {
	if offset < 0 || offset > src.len - 4 {
		range_panic('simd.load_u16x4_at', offset, src.len)
	}
	mut r := U16x4{}
	for i in 0 .. 4 {
		r.values[i] = src[offset + i]
	}
	return r
}

