// where it is clear.
@[direct_array_access]
pub fn select_u16x4(mask Mask16x4, a U16x4, b U16x4) U16x4 {
	mut r := U16x4{}
	$if @BACKEND == 'c' {
		native_select_u16(&mask.values[0], &a.values[0], &b.values[0], &r.values[0], 4)
	} $else {
		for i in 0 .. 4 {
			r.values[i] = if mask.values[i] != 0 { a.values[i] } else { b.values[i] }
		}
	}
	return r
}

