// [] returns lane i. It panics if i is out of range.
@[direct_array_access]
pub fn (v U16x4) [] (i int) u16 {
	if i < 0 || i >= 4 {
		lane_panic(i, 4)
	}
	return v.values[i]
}

// []= sets lane i to value. It panics if i is out of range.
@[direct_array_access]
pub fn (mut v U16x4) []= (i int, value u16) {
	if i < 0 || i >= 4 {
		lane_panic(i, 4)
	}
	v.values[i] = value
}

// store writes all 4 lanes to the start of dst.
// It returns an error if dst has fewer than 4 elements.
pub fn (v U16x4) store(mut dst []u16) ! {
	if dst.len < 4 {
		return error('simd.U16x4.store needs at least 4 values')
	}
	v.store_at(mut dst, 0)
}

// store_part writes one lane for each element of dst, up to 4 elements.
// It returns an error if dst has more than 4 elements.
@[direct_array_access]
pub fn (v U16x4) store_part(mut dst []u16) ! {
	if dst.len > 4 {
		return error('simd.U16x4.store_part accepts at most 4 values')
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&u16(dst.data) + 0, &v.values[0], dst.len * int(sizeof(u16))) }
	} $else {
		for i in 0 .. dst.len {
			dst[0 + i] = v.values[i]
		}
	}
}

// store_at writes all 4 lanes to dst, starting at dst[offset].
// It panics if offset is negative or fewer than 4 elements follow it.
@[direct_array_access]
pub fn (v U16x4) store_at(mut dst []u16, offset int) {
	if offset < 0 || offset > dst.len - 4 {
		range_panic('simd.U16x4.store_at', offset, dst.len)
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&u16(dst.data) + offset, &v.values[0], 4 * int(sizeof(u16))) }
	} $else {
		for i in 0 .. 4 {
			dst[offset + i] = v.values[i]
		}
	}
}

