}

// and returns the bitwise AND of corresponding lanes.
@[direct_array_access]
pub fn (a U16x16) and(b U16x16) U16x16 {
	mut r := U16x16{}
	$if @BACKEND == 'c' {
		native_and_u16(&a.values[0], &b.values[0], &r.values[0], 16)
	} $else {
		for i in 0 .. 16 {
			r.values[i] = a.values[i] & b.values[i]
		}
	}
	return r
}

// or returns the bitwise OR of corresponding lanes.
@[direct_array_access]
pub fn (a U16x16) or(b U16x16) U16x16 {
	mut r := U16x16{}
