// shl shifts each lane left by count bits.
// A count of 16 or more shifts every bit out and returns zero lanes.
@[direct_array_access]
pub fn (a U16x16) shl(count u32) U16x16 {
	if count >= 16 {
		return U16x16{}
	}
	mut r := U16x16{}
	$if @BACKEND == 'c' {
		native_shl_u16(&a.values[0], count, &r.values[0], 16)
	} $else {
		for i in 0 .. 16 {
			r.values[i] = u16(u32(a.values[i]) << count)
		}
	}
	return r
}

// shr shifts each lane right by count bits.
// A count of 16 or more shifts every bit out and returns zero lanes.
@[direct_array_access]
pub fn (a U16x16) shr(count u32) U16x16 {
	if count >= 16 {
		return U16x16{}
	}
	mut r := U16x16{}
	$if @BACKEND == 'c' {
		native_shr_u16(&a.values[0], count, &r.values[0], 16)
	} $else {
		for i in 0 .. 16 {
			r.values[i] = a.values[i] >> count
		}
	}
	return r
}

// sum adds the lanes, wrapping on overflow.
@[direct_array_access]
pub fn (v U16x16) sum() u16 {
	mut acc := u32(0)
	for i in 0 .. 16 {
		acc += u32(v.values[i])
	}
	return u16(acc)
}

// min_element returns the index of the first lane holding the smallest value.
@[direct_array_access]
pub fn (v U16x16) min_element() int {
	mut best := 0
	for i in 1 .. 16 {
		if v.values[i] < v.values[best] {
			best = i
		}
	}
	return best
}

// min returns the smallest lane value, the lane at index min_element().
@[direct_array_access]
pub fn (v U16x16) min() u16 {
	return v.values[v.min_element()]
}

// max_element returns the index of the first lane holding the largest value.
@[direct_array_access]
pub fn (v U16x16) max_element() int {
	mut best := 0
	for i in 1 .. 16 {
		if v.values[i] > v.values[best] {
