// U16x32 holds 32 u16 lanes (512 bits).
pub struct U16x32 {
mut:
	values [32]u16
}

// splat_u16x32 returns a U16x32 with every lane set to value.
pub fn splat_u16x32(value u16) U16x32 {
	return U16x32{
		values: [32]u16{init: value}
	}
}

// from_array_u16x32 returns a U16x32 holding values in lane order.
pub fn from_array_u16x32(values [32]u16) U16x32 {
	return U16x32{
		values: values
	}
}

// load_u16x32 loads 32 values from the start of src.
// It returns an error if src has fewer than 32 values.
pub fn load_u16x32(src []u16) !U16x32 {
	if src.len < 32 {
		return error('simd.load_u16x32 needs at least 32 values')
	}
	return load_u16x32_at(src, 0)
}

// load_u16x32_part loads up to 32 values from src and zero-fills the remaining lanes.
// It returns an error if src has more than 32 values.
@[direct_array_access]
pub fn load_u16x32_part(src []u16) !U16x32 {
	if src.len > 32 {
		return error('simd.load_u16x32_part accepts at most 32 values')
	}
	mut r := U16x32{}
	for i in 0 .. src.len {
		r.values[i] = src[i]
	}
	return r
}

// load_u16x32_at loads 32 values starting at src[offset].
// It panics if offset is negative or fewer than 32 values follow it.
@[direct_array_access]
pub fn load_u16x32_at(src []u16, offset int) U16x32 {
	if offset < 0 || offset > src.len - 32 {
		range_panic('simd.load_u16x32_at', offset, src.len)
	}
	mut r := U16x32{}
	for i in 0 .. 32 {
		r.values[i] = src[offset + i]
	}
	return r
}

// select_u16x32 returns the lanes of a where mask is set and the lanes of b
// where it is clear.
@[direct_array_access]
pub fn select_u16x32(mask Mask16x32, a U16x32, b U16x32) U16x32 {
	mut r := U16x32{}
	$if @BACKEND == 'c' {
		native_select_u16(&mask.values[0], &a.values[0], &b.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			r.values[i] = if mask.values[i] != 0 { a.values[i] } else { b.values[i] }
		}
	}
	return r
}

// to_array returns the lanes in order.
pub fn (v U16x32) to_array() [32]u16 {
	return v.values
}

// [] returns lane i. It panics if i is out of range.
@[direct_array_access]
pub fn (v U16x32) [] (i int) u16 {
	if i < 0 || i >= 32 {
		lane_panic(i, 32)
	}
	return v.values[i]
}

// []= sets lane i to value. It panics if i is out of range.
@[direct_array_access]
pub fn (mut v U16x32) []= (i int, value u16) {
	if i < 0 || i >= 32 {
		lane_panic(i, 32)
	}
	v.values[i] = value
}

// store writes all 32 lanes to the start of dst.
// It returns an error if dst has fewer than 32 elements.
pub fn (v U16x32) store(mut dst []u16) ! {
	if dst.len < 32 {
		return error('simd.U16x32.store needs at least 32 values')
	}
	v.store_at(mut dst, 0)
}

// store_part writes one lane for each element of dst, up to 32 elements.
// It returns an error if dst has more than 32 elements.
@[direct_array_access]
pub fn (v U16x32) store_part(mut dst []u16) ! {
	if dst.len > 32 {
		return error('simd.U16x32.store_part accepts at most 32 values')
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&u16(dst.data) + 0, &v.values[0], dst.len * int(sizeof(u16))) }
	} $else {
		for i in 0 .. dst.len {
			dst[0 + i] = v.values[i]
		}
	}
}

// store_at writes all 32 lanes to dst, starting at dst[offset].
// It panics if offset is negative or fewer than 32 elements follow it.
@[direct_array_access]
pub fn (v U16x32) store_at(mut dst []u16, offset int) {
	if offset < 0 || offset > dst.len - 32 {
		range_panic('simd.U16x32.store_at', offset, dst.len)
	}
	$if @BACKEND == 'c' {
		unsafe { vmemcpy(&u16(dst.data) + offset, &v.values[0], 32 * int(sizeof(u16))) }
	} $else {
		for i in 0 .. 32 {
			dst[offset + i] = v.values[i]
		}
	}
}

