// minimum returns the smaller of each pair of lanes.
@[direct_array_access]
pub fn (a U16x32) minimum(b U16x32) U16x32 {
	mut r := U16x32{}
	$if @BACKEND == 'c' {
		native_min_u16(&a.values[0], &b.values[0], &r.values[0], 32)
	} $else {
		for i in 0 .. 32 {
			x := a.values[i]
			y := b.values[i]
			r.values[i] = if y < x { y } else { x }
		}
	}
	return r
}

