// / divides corresponding lanes, truncating toward zero.
// It panics if a lane of b is zero.
@[direct_array_access]
pub fn (a U64x8) / (b U64x8) U64x8 {
	mut r := U64x8{}
	for i in 0 .. 8 {
		r.values[i] = a.values[i] / b.values[i]
	}
	return r
