// minimum returns the smaller of each pair of lanes.
@[direct_array_access]
pub fn (a U64x8) minimum(b U64x8) U64x8 {
	mut r := U64x8{}
	$if @BACKEND == 'c' {
		native_min_u64(&a.values[0], &b.values[0], &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			x := a.values[i]
			y := b.values[i]
			r.values[i] = if y < x { y } else { x }
		}
	}
	return r
}

