// shl shifts each lane left by count bits.
// A count of 64 or more shifts every bit out and returns zero lanes.
@[direct_array_access]
pub fn (a U64x8) shl(count u32) U64x8 {
	if count >= 64 {
		return U64x8{}
	}
	mut r := U64x8{}
	$if @BACKEND == 'c' {
		native_shl_u64(&a.values[0], count, &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			r.values[i] = u64(a.values[i]) << count
		}
	}
	return r
}

// shr shifts each lane right by count bits.
// A count of 64 or more shifts every bit out and returns zero lanes.
@[direct_array_access]
pub fn (a U64x8) shr(count u32) U64x8 {
	if count >= 64 {
		return U64x8{}
	}
	mut r := U64x8{}
	$if @BACKEND == 'c' {
		native_shr_u64(&a.values[0], count, &r.values[0], 8)
	} $else {
		for i in 0 .. 8 {
			r.values[i] = a.values[i] >> count
		}
	}
	return r
}

// sum adds the lanes, wrapping on overflow.
@[direct_array_access]
pub fn (v U64x8) sum() u64 {
	mut acc := u64(0)
	for i in 0 .. 8 {
		acc += v.values[i]
	}
	return acc
}

// min_element returns the index of the first lane holding the smallest value.
@[direct_array_access]
pub fn (v U64x8) min_element() int {
	mut best := 0
	for i in 1 .. 8 {
		if v.values[i] < v.values[best] {
			best = i
		}
	}
	return best
}

// min returns the smallest lane value, the lane at index min_element().
@[direct_array_access]
pub fn (v U64x8) min() u64 {
	return v.values[v.min_element()]
}

// max_element returns the index of the first lane holding the largest value.
@[direct_array_access]
pub fn (v U64x8) max_element() int {
	mut best := 0
	for i in 1 .. 8 {
		if v.values[i] > v.values[best] {
			best = i
		}
	}
	return best
}

// max returns the largest lane value, the lane at index max_element().
@[direct_array_access]
pub fn (v U64x8) max() u64 {
	return v.values[v.max_element()]
}

// dot multiplies corresponding lanes and adds the products, wrapping on overflow.
pub fn (a U64x8) dot(b U64x8) u64 {
	return (a * b).sum()
}

// to_f64x8 converts each lane to f64.
// It rounds to the nearest f64 value.
@[direct_array_access]
pub fn (v U64x8) to_f64x8() F64x8 {
	mut r := F64x8{}
	for i in 0 .. 8 {
		r.values[i] = f64(v.values[i])
	}
	return r
}

// to_i64x8 converts each lane to i64.
// It keeps the bits of each lane, so values wrap modulo 2^64.
@[direct_array_access]
pub fn (v U64x8) to_i64x8() I64x8 {
	mut r := I64x8{}
	for i in 0 .. 8 {
		r.values[i] = i64(v.values[i])
	}
	return r
}
